import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def feature_pairs(ctx):
    inputs = torch.randn(6, generator=ctx.rng.torch)
    teacher_features = torch.randn(2, 2, 2, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(inputs), "teacher_features": synth.Tensor(teacher_features)}
dataset = synth.Spec("gram-style", generator=feature_pairs, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class Student(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=6, out_features=8)
    def forward(self, inputs):
        return {"features": self.network(inputs).reshape(-1, 2, 2, 2)}
model = Student()
trainer = Trainer(model, train, recipe="structured-objective", recipe_config={"loss": "gram-loss", "bindings": {"logits_or_prediction": {"output": "features"}, "targets": {"batch": "teacher_features"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
